const n = Number($json.ia?.n_personas_detectadas ?? 0);

const categoria = n > 1 ? "HARD" : "SIMPLE";

return [{
  json: {
    ...$json,
    categoria,
  }
}];

// --- SIMPLE ---
// Output: persona, fecha, info, total

const ia = $json.ia ?? {};
const text = ($json.message?.text ?? ia.text ?? "").toString();

function parseFirstAmount(t) {
  const m = t.match(/(-?\d+(?:[.,]\d{1,2})?)\s*(?:€|eur|euros)?/i);
  if (!m) return 0;
  const n = Number(m[1].replace(",", "."));
  return Number.isFinite(n) ? n : 0;
}

// Persona: si IA detectó al menos 1, usamos la primera
const persona =
  Array.isArray(ia.personas) && ia.personas.length >= 1
    ? ia.personas[0]
    : "NO SE";

// Fecha
const fecha =
  $json.fecha ??
  (typeof $json.message?.date === "number"
    ? new Date($json.message.date * 1000).toISOString()
    : new Date().toISOString());

// ✅ INFO (una sola definición)
const info = ia.info ?? "NO SE";

// Total
const totalRaw =
  (typeof ia.cantidad_total === "number")
    ? ia.cantidad_total
    : parseFirstAmount(text);

const total = Number(totalRaw.toFixed(2));

return [{
  json: {
    ...$json,
    persona,
    fecha,
    info,
    total,
  }
}];

const raw = $json.output?.[0]?.content?.[0]?.text ?? "{}";

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { text: "", personas: [], n_personas_detectadas: 0, info: "NO SE", confidence: "baja" };
}

return [{ json: { ...$json, ia: parsed } }];

const text = ($json.message?.text ?? "").toString().trim();

// Detecta "METE" al inicio (ignorando mayúsculas/minúsculas y espacios)
const rama = /^mete\b/i.test(text) ? "METE" : "NO_METE";

return [{
  json: {
    ...$json,
    rama,
    text_original: text,
  }
}];

const raw = $json.output?.[0]?.content?.[0]?.text ?? "{}";

let mete;
try {
  mete = JSON.parse(raw);
} catch (e) {
  mete = { text: "", total: 0, gasto: "NO SE", categoria: "NO SE", confidence: "baja" };
}

// Normaliza por si viene total como string
const totalNum = Number(String(mete.total ?? 0).replace(",", "."));
mete.total = Number.isFinite(totalNum) ? Number(totalNum.toFixed(2)) : 0;

// Limpieza extra
mete.gasto = (mete.gasto ?? "NO SE").toString().trim() || "NO SE";
mete.categoria = (mete.categoria ?? "NO SE").toString().trim().toUpperCase() || "NO SE";

return [{
  json: {
    ...$json,
    mete,                // objeto completo
    total: mete.total,   // atajos por si quieres mapear fácil a Sheets
    gasto: mete.gasto,
    categoria: mete.categoria,
  }
}];

// --- HARD ---
// Caso: más de una persona
// persona = "A, B, C"
// total = importe tal cual (NO dividir)

const ia = $json.ia ?? {};
const text = ($json.message?.text ?? ia.text ?? "").toString();

function parseFirstAmount(t) {
  const m = t.match(/(-?\d+(?:[.,]\d{1,2})?)\s*(?:€|eur|euros)?/i);
  if (!m) return 0;
  const n = Number(m[1].replace(",", "."));
  return Number.isFinite(n) ? n : 0;
}

// Personas (ya sabemos que hay >1)
const personasArr = Array.isArray(ia.personas) ? ia.personas : [];
const persona = personasArr.length ? personasArr.join(", ") : "NO SE";

// Fecha
const fecha =
  $json.fecha ??
  (typeof $json.message?.date === "number"
    ? new Date($json.message.date * 1000).toISOString()
    : new Date().toISOString());

// Info
const info = ia.info ?? "NO SE";

// Total (sin dividir)
const totalRaw =
  (typeof ia.cantidad_total === "number")
    ? ia.cantidad_total
    : parseFirstAmount(text);

const total = Number(totalRaw.toFixed(2));

return [{
  json: {
    ...$json,
    persona,
    fecha,
    info,
    total,
  }
}];
